@staticmethod
def read_file(file_path):
    if file_path.endswith(".ini"):
        cf = configparser.ConfigParser()
        cf.read(file_path, encoding=ENCODE_UTF_8)
        return cf
    elif file_path.endswith(".csv"):
        csv_buf = []
        with open(file_path, mode="r", encoding=ENCODE_UTF_8) as f:
            reader = csv.reader(f)
            for row in reader:
                csv_buf.append(row)
        return csv_buf
    else:
        with open(file_path, mode="r", encoding=ENCODE_UTF_8) as f:
            file_buf = f.read()
        return file_buf

